reference_solution:
def minimum_xor_removals(nums,target):
    states={0:0}
    for value in nums:
        updated=states.copy()
        for xor,count in states.items():updated[xor^value]=max(updated.get(xor^value,-1),count+1)
        states=updated
    return -1 if target not in states else len(nums)-states[target]

